package ps4pkg

import (
	"crypto/rsa"
	"encoding/hex"
	"math/big"
)

// RSA private keys used to decrypt fake (non-finalized) PS4 packages.
// Key material is the well-known fake PKG keyset published by OpenOrbis
// LibOrbisPkg (LGPL-3.0), originally recovered by flatz/maxton.
//
// These keys decrypt IMAGE_KEY / derived-key slot 3 on fake packages only.
// Retail finalized packages require a per-title passcode or EKPFS.

func mustHex(s string) []byte {
	b, err := hex.DecodeString(s)
	if err != nil {
		panic("ps4pkg: invalid embedded key hex: " + err.Error())
	}
	return b
}

func rsaPrivateFromBE(mod, d, p, q []byte) *rsa.PrivateKey {
	key := &rsa.PrivateKey{
		PublicKey: rsa.PublicKey{
			N: new(big.Int).SetBytes(mod),
			E: 65537,
		},
		D:      new(big.Int).SetBytes(d),
		Primes: []*big.Int{new(big.Int).SetBytes(p), new(big.Int).SetBytes(q)},
	}
	key.Precompute()
	return key
}

